      "motherboard": "mb-gb-b650-aorus-elite-ax",
      "memory": "mem-gskill-flarex5-32-6000",
      "ssd": [
        {
          "sku": "ssd-crucial-t500-2tb",
          "quantity": 1
        }
      ],
      "psu": "psu-seasonic-vertex-gx1000",
      "case": "case-coolermaster-td500-mesh-v2",
      "cooler": "cooler-arctic-lf3-360"
    },
    "rationale": {
      "cpu": "Ryzen 7 9800X3D是当前顶级游戏CPU，3D V-Cache对绝地求生等高帧率游戏收益显著，AM5平台支持DDR5与未来升级",
      "gpu": "RTX 4080 SUPER 16GB可在4K高画质下运行绝地求生并接近144fps目标，优先GPU预算分配",
      "motherboard": "B650 AORUS ELITE AX为AM5 DDR5主板，供电与扩展满足9800X3D需求，价格适中",
      "memory": "DDR5-6000 CL30 32GB套装兼顾频率与时序，适配AM5甜点频率",
      "ssd": "Crucial T500 2TB NVMe PCIe4.0高速固态，容量充足且加载迅速",
      "psu": "VERTEX GX-1000原生16pin接口直连4080S，1000W金牌冗余充足",
      "case": "TD500 Mesh V2支持ATX主板与360冷排，GPU限长410mm兼容4080S",
      "cooler": "Liquid Freezer III 360压制9800X3D绰绰有余，静音与散热均衡"
    }
  },
  "assessments": [
    {
      "field": "budget_cny",
      "status": "met",
      "explanation": "总价23431.08元，低于25000元预算上限",
      "evidence": ["local:cpu-r7-9800x3d", "local:gpu-asus-4080s-tuf", "local:mb-gb-b650-aorus-elite-ax", "local:mem-gskill-flarex5-32-6000", "local:ssd-crucial-t500-2tb", "local:psu-seasonic-vertex-gx1000", "local:case-coolermaster-td500-mesh-v2", "local:cooler-arctic-lf3-360"]
    },
    {
      "field": "use_case.type",
      "status": "met",
      "explanation": "全套配件面向高性能游戏场景选配，GPU/CPU均为当前游戏旗舰级",
      "evidence": ["local:cpu-r7-9800x3d", "local:gpu-asus-4080s-tuf"]
    },
    {
      "field": "use_case.titles",
      "status": "met",
      "explanation": "绝地求生为CPU/GPU敏感型竞技游戏，9800X3D+4080S组合在4K分辨率下具备达成高帧率的硬件基础",
      "evidence": ["local:cpu-r7-9800x3d", "local:gpu-asus-4080s-tuf"]
    },
    {
      "field": "use_case.resolution",
      "status": "met",
      "explanation": "RTX 4080 SUPER 16GB显存与光栅性能足以支撑4K渲染，TUF型号三槽散热保障持续输出",
      "evidence": ["local:gpu-asus-4080s-tuf"]
    },
    {
      "field": "use_case.fps_target",
      "status": "unknown",
      "explanation": "4K 144fps为极高目标，4080S在绝地求生4K超高画质下通常可达100-130fps，需降低部分设置或启用DLSS方可稳定144；无该游戏+硬件组合的权威实测数据，不承诺确定帧率",
      "evidence": ["local:gpu-asus-4080s-tuf", "local:cpu-r7-9800x3d"]
    },
    {
      "field": "priority",
      "status": "met",
      "explanation": "GPU占整机预算38%，为最高单价配件，符合优先GPU的软偏好",
      "evidence": ["local:gpu-asus-4080s-tuf"]
    }
  ],
  "issues": [],
  "assumptions": [
    "用户未指定品牌偏好、机箱尺寸、静音要求或已有配件，故自主选择主流高性价比型号",
    "内存频率兼容性基于B650 AORUS ELITE AX官方规格推断，目录字段缺失不影响实际使用",
    "散热器性能基于360mm AIO通用规格判断，足以应对120W TDP处理器",
    "4K 144fps目标为理论选型方向，实际表现取决于游戏设置、驱动优化及系统调校，非保证值"
  ]
}

